    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address callerIsNotOwner) public payable {
        require(callerIsNotOwner != address(0));
        require(c.smartfix_owner() != address(this), "test contract must not be owner");
        address owner = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        require(callerIsNotOwner != owner);
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }
    receive() external payable { }
}

