// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(address callerIsNotOwner) internal {
        vm.assume(callerIsNotOwner != address(0));
        vm.assume(c.smartfix_owner() != address(this));
        address owner;
        try c.smartfix_owner() returns (address __r) { owner = __r; } catch { return; }
        vm.assume(callerIsNotOwner != owner);
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(address callerIsNotOwner) public {
        vm.assume(callerIsNotOwner.code.length == 0 && uint160(callerIsNotOwner) > 0xffff && callerIsNotOwner != address(this) && callerIsNotOwner != address(c) && callerIsNotOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && callerIsNotOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && callerIsNotOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && callerIsNotOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(callerIsNotOwner);
    }

    receive() external payable { }
}
